mapper.select:
SELECT 
FROM audit_log al
LEFT JOIN app_user u ON u.id = al.actor_id
WHERE al.workspace_id = #{workspaceId}
ORDER BY al.created_at DESC, al.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM audit_log al
LEFT JOIN app_user u ON u.id = al.actor_id
WHERE al.workspace_id = #{workspaceId} AND al.entity_type = #{entityType} AND al.entity_id = #{entityId}
ORDER BY al.created_at DESC, al.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM audit_log al
LEFT JOIN app_user u ON u.id = al.actor_id
WHERE al.workspace_id = #{workspaceId}
ORDER BY al.chain_index IS NULL, al.chain_index ASC, al.created_at ASC, al.id ASC
LIMIT #{limit} OFFSET #{offset}
